 S(1,"Los recursos",[T("Tres recursos muy usados",["Recurso","Qué hace","Ejemplo"],[["Lo inesperado","Rompe lo que esperábamos","Alguien busca sus anteojos una hora y los tenía puestos"],["Exageración","Agranda algo hasta volverlo absurdo","Era tan alto que, para saludarlo, había que mandarle un mensaje"],["Juego de palabras","Usa una palabra con dos sentidos","El electricista tenía un mal día: todo le daba corto"]])]),
 S(2,"Reconocer un recurso",[E("Un ejemplo","Reconocer el recurso en: «Mi abuelo es tan despistado que ayer buscó sus anteojos durante una hora… y los tenía puestos».",["Se arma una expectativa: alguien que busca algo perdido.","El final la rompe: los anteojos estaban puestos.","El recurso es lo inesperado."]),
  P("Un mismo chiste puede usar más de un recurso a la vez. Para reconocerlos, conviene preguntarse tres cosas: qué esperaba el lector, qué pasó en realidad y qué se agrandó o se dijo con doble sentido.")]),
